#' Agreement: Continuous Measurements (Python)
#'
#' 
#' @param data .
#' @param vars .
#' @param subject .
#' @param baConfidenceLevel .
#' @param confLevel .
#' @param showPairs .
#' @param blandAltmanPlot .
#' @param method .
#' @param iccType .
#' @param showICCCases .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$statistics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pairs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$iccAudit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iccStatistics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iccRaters} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$iccCases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyagreement <- function(
    data,
    vars = NULL,
    subject = NULL,
    baConfidenceLevel = 0.95,
    confLevel = 0.95,
    showPairs = FALSE,
    blandAltmanPlot = FALSE,
    method = "blandaltman",
    iccType = "icc21",
    showICCCases = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyagreement requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(subject), subject, NULL))


    options <- pyagreementOptions$new(
        vars = vars,
        subject = subject,
        baConfidenceLevel = baConfidenceLevel,
        confLevel = confLevel,
        showPairs = showPairs,
        blandAltmanPlot = blandAltmanPlot,
        method = method,
        iccType = iccType,
        showICCCases = showICCCases,
        showConsole = showConsole)

    analysis <- pyagreementClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

